func TestCoverage(t *testing.T) {
	ctx, done := testx.Context(t)
	defer done()

	t.Run("parses lcov.info at root level", func(t *testing.T) {
		dir := t.TempDir()
		content := "SF:src/main.go\nFN:1,main\nFNDA:3,main\nLF:10\nLH:5\nBRF:4\nBRH:2\nend_of_record\n"
		require.NoError(t, os.WriteFile(filepath.Join(dir, "lcov.info"), []byte(content), 0o644))

		var reports []*coverage.Report
		for rep, err := range lcov.Coverage(ctx, dir) {
			require.NoError(t, err)
			require.NotNil(t, rep)
			reports = append(reports, rep)
		}

		require.Len(t, reports, 2)
		require.Equal(t, "src/main.go", reports[0].Path)
		require.Equal(t, float32(50), reports[0].Statements)
		require.Equal(t, float32(50), reports[0].Branches)
		require.Equal(t, "", reports[0].Fnname)
		require.Equal(t, "main", reports[1].Fnname)
		require.Equal(t, int64(3), reports[1].Hits)
	})

	t.Run("finds lcov.info in nested subdirectories", func(t *testing.T) {
		dir := t.TempDir()
		sub := filepath.Join(dir, "deep", "nested")
		require.NoError(t, os.MkdirAll(sub, 0o755))
		content := "SF:src/child.go\nLF:4\nLH:4\nBRF:0\nBRH:0\nend_of_record\n"
		require.NoError(t, os.WriteFile(filepath.Join(sub, "lcov.info"), []byte(content), 0o644))

		var reports []*coverage.Report
		for rep, err := range lcov.Coverage(ctx, dir) {
			require.NoError(t, err)
			require.NotNil(t, rep)
			reports = append(reports, rep)
		}

		require.Len(t, reports, 1)
		require.Equal(t, "src/child.go", reports[0].Path)
		require.Equal(t, float32(100), reports[0].Statements)
		require.Equal(t, float32(0), reports[0].Branches)
	})

	t.Run("skips files that are not named lcov.info", func(t *testing.T) {
		dir := t.TempDir()
		require.NoError(t, os.WriteFile(filepath.Join(dir, "other.txt"), []byte("not lcov"), 0o644))
		require.NoError(t, os.WriteFile(filepath.Join(dir, "coverage.lcov"), []byte("SF:x\nLF:1\nLH:1\nend_of_record\n"), 0o644))

		var reports []*coverage.Report
		for rep, err := range lcov.Coverage(ctx, dir) {
			require.NoError(t, err)
			if rep != nil {
				reports = append(reports, rep)
			}
		}

		require.Empty(t, reports)
	})

	t.Run("yields nothing for empty directory", func(t *testing.T) {
		dir := t.TempDir()

		var reports []*coverage.Report
		var errs []error
		for rep, err := range lcov.Coverage(ctx, dir) {
			if err != nil {
				errs = append(errs, err)
			}
			if rep != nil {
				reports = append(reports, rep)
			}
		}

		require.Empty(t, reports)
		require.Empty(t, errs)
	})

	t.Run("parses multiple lcov.info files in different subdirectories", func(t *testing.T) {
		dir := t.TempDir()
		subA := filepath.Join(dir, "a")
		subB := filepath.Join(dir, "b")
		require.NoError(t, os.MkdirAll(subA, 0o755))
		require.NoError(t, os.MkdirAll(subB, 0o755))

		contentA := "SF:src/a.go\nLF:2\nLH:1\nBRF:0\nBRH:0\nend_of_record\n"
		contentB := "SF:src/b.go\nLF:4\nLH:3\nBRF:0\nBRH:0\nend_of_record\n"
		require.NoError(t, os.WriteFile(filepath.Join(subA, "lcov.info"), []byte(contentA), 0o644))
		require.NoError(t, os.WriteFile(filepath.Join(subB, "lcov.info"), []byte(contentB), 0o644))

		var reports []*coverage.Report
		for rep, err := range lcov.Coverage(ctx, dir) {
			require.NoError(t, err)
			require.NotNil(t, rep)
			reports = append(reports, rep)
		}

		require.Len(t, reports, 2)
		require.Equal(t, "src/a.go", reports[0].Path)
		require.Equal(t, float32(50), reports[0].Statements)
		require.Equal(t, "src/b.go", reports[1].Path)
		require.Equal(t, float32(75), reports[1].Statements)
	})

	t.Run("parses lcov.info with multiple source files", func(t *testing.T) {
		dir := t.TempDir()
		content := "SF:src/one.go\nLF:10\nLH:10\nBRF:2\nBRH:2\nend_of_record\nSF:src/two.go\nLF:20\nLH:10\nBRF:4\nBRH:0\nend_of_record\n"
		require.NoError(t, os.WriteFile(filepath.Join(dir, "lcov.info"), []byte(content), 0o644))

		var reports []*coverage.Report
		for rep, err := range lcov.Coverage(ctx, dir) {
			require.NoError(t, err)
			require.NotNil(t, rep)
			reports = append(reports, rep)
		}

		require.Len(t, reports, 2)
		require.Equal(t, "src/one.go", reports[0].Path)
		require.Equal(t, float32(100), reports[0].Statements)
		require.Equal(t, float32(100), reports[0].Branches)
		require.Equal(t, "src/two.go", reports[1].Path)
		require.Equal(t, float32(50), reports[1].Statements)
		require.Equal(t, float32(0), reports[1].Branches)
	})

	t.Run("reports error for non-existent directory", func(t *testing.T) {
		dir := filepath.Join(t.TempDir(), "does-not-exist")

		var err error
		var reports []*coverage.Report
		for rep, e := range lcov.Coverage(ctx, dir) {
			if e != nil {
				err = e
			}
			if rep != nil {
				reports = append(reports, rep)
			}
		}

		require.Error(t, err)
		require.Empty(t, reports)
	})

	t.Run("yields function rows alongside file rows", func(t *testing.T) {
		dir := t.TempDir()
		content := "SF:src/app.ts\nFN:1,init\nFNDA:2,init\nFN:5,run\nFNDA:0,run\nLF:8\nLH:4\nBRF:6\nBRH:3\nend_of_record\n"
		require.NoError(t, os.WriteFile(filepath.Join(dir, "lcov.info"), []byte(content), 0o644))

		var reports []*coverage.Report
		for rep, err := range lcov.Coverage(ctx, dir) {
			require.NoError(t, err)
			require.NotNil(t, rep)
			reports = append(reports, rep)
		}

		require.Len(t, reports, 3)
		require.Equal(t, "src/app.ts", reports[0].Path)
		require.Equal(t, "", reports[0].Fnname)
		require.Equal(t, float32(50), reports[0].Statements)
		require.Equal(t, float32(50), reports[0].Branches)
		require.Equal(t, "init", reports[1].Fnname)
		require.Equal(t, int64(2), reports[1].Hits)
		require.Equal(t, "run", reports[2].Fnname)
		require.Equal(t, int64(0), reports[2].Hits)
	})
}
